1:/*
2: * VelaWear Agent - IMU Sensor Driver Implementation
3: *
4: * Reads LSM6DSL IMU data for motion detection.
5: *
6: * Author: pjjuihj
7: * Team: 329 - dela
8: */
9:
10:#include <nuttx/config.h>
11:#include <stdio.h>
12:#include <stdlib.h>
13:#include <string.h>
14:#include <fcntl.h>
15:#include <unistd.h>
16:#include <errno.h>
17:#include <syslog.h>
18:#include <sys/ioctl.h>
19:#include <math.h>
20:#include <time.h>
21:
22:#include "velawear.h"
23:#include "imu_sensor.h"
24:
25:/****************************************************************************
26: * Pre-processor Definitions
27: ****************************************************************************/
28:
29:/* The Huangshan Pi board registers the LSM6DSL as /dev/lsm6dsl0. */
30:#define IMU_DEVICE_PATH         "/dev/lsm6dsl0"
31:
32:/* Motion thresholds are based on dynamic acceleration in g. */
33:
34:#define DEFAULT_MOVE_THRESHOLD  0.08f
35:#define DEFAULT_RUN_THRESHOLD   0.35f
36:#define DEFAULT_FALL_THRESHOLD  15.0f
37:
38:#define GRAVITY_FILTER_ALPHA    0.05f
39:
40:#define FALL_FREEFALL_THRESHOLD 0.5f
41:#define FALL_IMPACT_THRESHOLD   8.0f
42:#define FALL_REST_MIN           0.7f
43:#define FALL_REST_MAX           1.3f
44:#define FALL_FREEFALL_WINDOW_MS 500
45:#define FALL_FREEFALL_MIN_MS    100
46:#define FALL_IMPACT_WINDOW_MS   2000
47:#define FALL_CONFIRM_HOLD_MS    2000
48:
49:/****************************************************************************
50: * Private Functions
51: ****************************************************************************/
52:
53:static float calculate_magnitude(float x, float y, float z)
54:{
55:  return sqrtf(x * x + y * y + z * z);
56:}
57:
58:static uint32_t imu_now_ms(void)
59:{
60:  struct timespec ts;
61:
62:  if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0)
63:    {
64:      return (uint32_t)time(NULL) * 1000;
65:    }
66:
67:  return (uint32_t)(ts.tv_sec * 1000 + ts.tv_nsec / 1000000);
68:}
69:
70:static void reset_fall_detector(imu_sensor_t *imu)
71:{
72:  imu->fall_detector.stage = FALL_STAGE_NONE;
73:  imu->fall_detector.stage_start_ms = 0;
74:  imu->fall_detector.confirmed = false;
75:}
76:
77:static void update_fall_detector(imu_sensor_t *imu, float accel_mag)
78:{
79:  uint32_t now = imu_now_ms();
80:  uint32_t elapsed = now - imu->fall_detector.stage_start_ms;
81:
82:  switch (imu->fall_detector.stage)
83:    {
84:      case FALL_STAGE_NONE:
85:        if (accel_mag < FALL_FREEFALL_THRESHOLD)
86:          {
87:            imu->fall_detector.stage = FALL_STAGE_FREEFALL;
88:            imu->fall_detector.stage_start_ms = now;
89:            imu->fall_detector.confirmed = false;
90:          }
91:        break;
92:
93:      case FALL_STAGE_FREEFALL:
94:        if (accel_mag > FALL_IMPACT_THRESHOLD &&
95:            elapsed >= FALL_FREEFALL_MIN_MS &&
96:            elapsed <= FALL_FREEFALL_WINDOW_MS)
97:          {
98:            imu->fall_detector.stage = FALL_STAGE_IMPACT;
99:            imu->fall_detector.stage_start_ms = now;
100:          }
101:        else if (accel_mag >= FALL_FREEFALL_THRESHOLD ||
102:                 elapsed > FALL_FREEFALL_WINDOW_MS)
103:          {
104:            /* Freefall must remain below 0.5g until the impact sample. */
105:            reset_fall_detector(imu);
106:          }
107:        break;
108:
109:      case FALL_STAGE_IMPACT:
110:        if (accel_mag >= FALL_REST_MIN && accel_mag <= FALL_REST_MAX &&
111:            elapsed <= FALL_IMPACT_WINDOW_MS)
112:          {
113:            imu->fall_detector.stage = FALL_STAGE_STILL;
114:            imu->fall_detector.stage_start_ms = now;
115:            imu->fall_detector.confirmed = true;
116:            syslog(LOG_WARNING,
117:                   "[IMU] Fall confirmed after freefall and impact\n");
118:          }
119:        else if (elapsed > FALL_IMPACT_WINDOW_MS)
120:          {
121:            reset_fall_detector(imu);
122:          }
123:        break;
124:
125:      case FALL_STAGE_STILL:
126:        if (elapsed > FALL_CONFIRM_HOLD_MS)
127:          {
128:            reset_fall_detector(imu);
129:          }
130:        break;
131:
132:      default:
133:        reset_fall_detector(imu);
134:        break;
135:    }
136:
137:  imu->motion.fall_detected = imu->fall_detector.confirmed;
138:}
139:
140:static void update_motion_state(imu_sensor_t *imu, imu_data_t *data)
141:{
142:  float accel_mag = calculate_magnitude(data->accel_x,
143:                                        data->accel_y,
144:                                        data->accel_z);
145:  float dynamic_x;
146:  float dynamic_y;
147:  float dynamic_z;
148:  float dynamic_mag;
149:  float gyro_mag = calculate_magnitude(data->gyro_x,
150:                                       data->gyro_y,
151:                                       data->gyro_z);
152:
153:  /* Remove the slowly changing gravity vector before deciding activity.
154:   * A stationary board reports about 1g, which must not count as motion. */
155:
156:  if (!imu->gravity_valid)
157:    {
158:      imu->gravity_x = data->accel_x;
159:      imu->gravity_y = data->accel_y;
160:      imu->gravity_z = data->accel_z;
161:      imu->gravity_valid = true;
162:    }
163:  else
164:    {
165:      imu->gravity_x += GRAVITY_FILTER_ALPHA *
166:                        (data->accel_x - imu->gravity_x);
167:      imu->gravity_y += GRAVITY_FILTER_ALPHA *
168:                        (data->accel_y - imu->gravity_y);
169:      imu->gravity_z += GRAVITY_FILTER_ALPHA *
170:                        (data->accel_z - imu->gravity_z);
171:    }
172:
173:  dynamic_x = data->accel_x - imu->gravity_x;
174:  dynamic_y = data->accel_y - imu->gravity_y;
175:  dynamic_z = data->accel_z - imu->gravity_z;
176:  dynamic_mag = calculate_magnitude(dynamic_x, dynamic_y, dynamic_z);
177:
178:  /* Confirm a fall only after freefall, impact, and post-impact stillness. */
179:
180:  update_fall_detector(imu, accel_mag);
181:
182:  /* Check for running (high acceleration + gyro) */
183:
184:  if (dynamic_mag > imu->threshold_run && gyro_mag > 1.0f)
185:    {
186:      imu->motion.is_running = true;
187:      imu->motion.is_moving = true;
188:      imu->motion.last_motion_time = time(NULL);
189:      imu->motion.motion_count++;
190:    }
191:  /* Check for moving (moderate acceleration) */
192:
193:  else if (dynamic_mag > imu->threshold_move)
194:    {
195:      imu->motion.is_moving = true;
196:      imu->motion.is_running = false;
197:      imu->motion.last_motion_time = time(NULL);
198:      imu->motion.motion_count++;
199:    }
200:  else
201:    {
202:      /* No significant motion */
203:
204:      if (time(NULL) - imu->motion.last_motion_time > 5)
205:        {
206:          imu->motion.is_moving = false;
207:          imu->motion.is_running = false;
208:        }
209:    }
210:
211:  imu->motion.motion_intensity = dynamic_mag;
212:}
