216: ****************************************************************************/
217:
218:int imu_sensor_init(imu_sensor_t *imu)
219:{
220:  memset(imu, 0, sizeof(imu_sensor_t));
221:
222:  /* Open IMU device */
223:
224:  imu->fd = open(IMU_DEVICE_PATH, O_RDONLY);
225:  if (imu->fd < 0)
226:    {
227:      syslog(LOG_ERR, "[IMU] Failed to open %s: %d\n",
228:             IMU_DEVICE_PATH, errno);
229:      return VELAWEAR_ERR_IO;
230:    }
231:
232:  /* Start the sensor before requesting samples.  The LSM6DSL driver exposes
233:   * data through SNIOC_LSM6DSLSENSORREAD rather than read(). */
234:  if (ioctl(imu->fd, SNIOC_START, 0) < 0)
235:    {
236:      syslog(LOG_ERR, "[IMU] Failed to start %s: %d\n",
237:             IMU_DEVICE_PATH, errno);
238:      close(imu->fd);
239:      imu->fd = -1;
240:      return VELAWEAR_ERR_IO;
241:    }
242:
243:  /* Set default thresholds */
244:
245:  imu->threshold_move = DEFAULT_MOVE_THRESHOLD;
246:  imu->threshold_run = DEFAULT_RUN_THRESHOLD;
247:  imu->threshold_fall = DEFAULT_FALL_THRESHOLD;
248:
249:  imu->initialized = true;
250:  imu->buffer_index = 0;
251:
252:  syslog(LOG_INFO, "[IMU] Initialized\n");
253:  return VELAWEAR_OK;
254:}
255:
256:void imu_sensor_cleanup(imu_sensor_t *imu)
257:{
258:  if (imu->fd >= 0)
259:    {
260:      close(imu->fd);
261:    }
262:
263:  imu->initialized = false;
264:  syslog(LOG_INFO, "[IMU] Cleaned up\n");
265:}
266:
267:int imu_sensor_read(imu_sensor_t *imu, imu_data_t *data)
268:{
269:  struct lsm6dsl_sensor_data_s raw;
270:  int ret;
271:
272:  if (!imu->initialized)
273:    {
274:      return VELAWEAR_ERR_IO;
275:    }
276:
277:  ret = ioctl(imu->fd, SNIOC_LSM6DSLSENSORREAD,
278:              (unsigned long)&raw);
279:  if (ret < 0)
280:    {
281:      syslog(LOG_ERR, "[IMU] Read failed: %d\n", errno);
282:      return VELAWEAR_ERR_IO;
283:    }
284:
285:  /* Convert raw data to float */
286:
287:  data->accel_x = raw.x_data / 1000.0f;
288:  data->accel_y = raw.y_data / 1000.0f;
289:  data->accel_z = raw.z_data / 1000.0f;
290:  data->gyro_x = raw.g_x_data / 1000.0f;
291:  data->gyro_y = raw.g_y_data / 1000.0f;
292:  data->gyro_z = raw.g_z_data / 1000.0f;
293:  data->timestamp = time(NULL);
294:
295:  /* Store in buffer */
296:
297:  imu->buffer[imu->buffer_index] = *data;
298:  imu->buffer_index = (imu->buffer_index + 1) % IMU_BUFFER_SIZE;
299:
300:  /* Update motion state */
301:
302:  update_motion_state(imu, data);
303:
304:  return VELAWEAR_OK;
305:}
306:
307:int imu_sensor_read_buffer(imu_sensor_t *imu, imu_data_t *buffer,
308:                           int max_count)
309:{
310:  int count = 0;
311:
312:  for (int i = 0; i < max_count; i++)
313:    {
314:      if (imu_sensor_read(imu, &buffer[count]) < 0)
315:        {
316:          break;
317:        }
318:
319:      count++;
320:    }
321:
322:  return count;
323:}
