182:  action.type = VELAWEAR_ACTION_SHOW_UI;
183:  action.priority = VELAWEAR_PRIORITY_NORMAL;
184:  snprintf(action.params.display.text, sizeof(action.params.display.text),
185:           "该活动一下了\n检测到持续静止");
