203:static void *decision_engine_thread(void *arg)
204:{
205:  velawear_engine_t *engine = (velawear_engine_t *)arg;
206:  velawear_state_t state;
207:  velawear_event_t event;
208:  int ret;
209:
210:  syslog(LOG_INFO, "[Decision] Thread started\n");
211:
212:  while (engine->running)
213:    {
214:      /* Sleep for decision interval */
215:
216:      usleep(100000);  /* 100ms */
217:
218:      /* Get current state */
219:
220:      /* The event-driven path supplies real state and events.  Keep this
221:       * worker safe for callers that explicitly start it by using neutral
222:       * values instead of uninitialized stack data. */
223:      memset(&state, 0, sizeof(state));
224:      memset(&event, 0, sizeof(event));
225:      state.battery_level = 100;
226:      state.heart_rate = 60.0f;
227:      state.is_charging = true;
228:
229:      /* TODO: Get state from state manager */
230:
231:      /* Evaluate rules by priority */
232:
233:      pthread_mutex_lock(&engine->lock);
234:
235:      for (int i = 0; i < engine->rule_count; i++)
236:        {
237:          if (!engine->rules[i].enabled)
238:            {
239:              continue;
240:            }
241:
242:          if (engine->rules[i].condition &&
243:              engine->rules[i].condition(&state, &event,
244:                                         engine->rules[i].context))
245:            {
246:              ret = engine->rules[i].action(&state,
247:                                            engine->rules[i].context);
248:              if (ret < 0)
249:                {
250:                  syslog(LOG_WARNING,
251:                         "[Decision] Rule '%s' action failed: %d\n",
252:                         engine->rules[i].name, ret);
253:                }
254:
255:              /* For emergency rules, stop after first match */
256:
257:              if (engine->rules[i].layer == 0)
258:                {
259:                  break;
260:                }
261:            }
262:        }
263:
264:      pthread_mutex_unlock(&engine->lock);
265:    }
266:
267:  syslog(LOG_INFO, "[Decision] Thread stopped\n");
268:  return NULL;
269:}
