835:static int velawear_start(velawear_agent_t *agent)
836:{
837:  int ret;
838:
839:  /* The main loop owns event queue consumption.  Do not start a second
840:   * consumer thread for the same mqueue. */
841:
842:  /* Start action manager thread. */
843:
844:  ret = action_manager_start(&agent->actions);
845:  if (ret < 0)
846:    {
847:      syslog(LOG_ERR, "[VelaWear] Action manager start failed: %d\n", ret);
848:      return ret;
849:    }
850:
851:  /* Decision rules are evaluated synchronously for each event. */
852:
853:  /* Mark agent as running before starting the sensor producer. */
854:
855:  agent->running = true;
856:  ret = velawear_watchdog_start(agent);
857:  if (ret < 0)
858:    {
859:      agent->running = false;
860:      return ret;
861:    }
862:
863:  if (agent->imu.initialized)
864:    {
865:      ret = pthread_create(&agent->imu_thread, NULL,
866:                           velawear_imu_thread, agent);
867:      if (ret != 0)
868:        {
869:          agent->running = false;
870:          syslog(LOG_ERR, "[VelaWear] IMU thread start failed: %d\n", ret);
871:          return VELAWEAR_ERR_IO;
872:        }
873:      agent->imu_thread_started = true;
874:    }
875:
876:  return VELAWEAR_OK;
877:}
