910:static int velawear_event_handler(velawear_event_t *event, void *context)
911:{
912:  velawear_agent_t *agent = (velawear_agent_t *)context;
913:  velawear_state_t state;
914:  velawear_action_t action;
915:  int rule_id;
916:  int ret;
917:
918:  ret = state_manager_update_from_event(&agent->state_mgr, event);
919:  if (ret < 0)
920:    {
921:      return ret;
922:    }
923:
924:  state = state_manager_get_state(&agent->state_mgr);
925:  agent->state = state;
926:  rule_id = decision_engine_evaluate(&agent->engine, &state, event);
927:
928:  /* Every matched rule produces a traceable action.  Rule-specific handlers
929:   * can replace this log action later without changing the event pipeline. */
930:  if (rule_id >= 0 && event->type != VELAWEAR_EVENT_MOTION &&
931:      event->type != VELAWEAR_EVENT_FALL)
932:    {
933:      memset(&action, 0, sizeof(action));
934:      action.type = VELAWEAR_ACTION_LOG;
935:      action.priority = event->priority;
936:      ret = action_manager_execute(&agent->actions, &action);
937:      if (ret < 0)
938:        {
939:          return ret;
940:        }
941:    }
942:
943:  /* The action manager worker performs callbacks; wake it after evaluation. */
944:  return action_manager_process(&agent->actions);
945:}
