23:/****************************************************************************
24: * Hardcoded Rules (Layer 0 - Emergency)
25: ****************************************************************************/
26:
27:static bool fall_detected_condition(velawear_state_t *state,
28:                                    velawear_event_t *event,
29:                                    void *context)
30:{
31:  (void)state;
32:  (void)context;
33:  return event && event->type == VELAWEAR_EVENT_FALL;
34:}
35:
36:static int fall_detected_action(velawear_state_t *state, void *context)
37:{
38:  velawear_engine_t *engine = (velawear_engine_t *)context;
39:  velawear_action_t action;
40:  int ret;
41:
42:  if (engine == NULL || engine->actions == NULL)
43:    {
44:      return VELAWEAR_ERR_INVAL;
45:    }
46:
47:  memset(&action, 0, sizeof(action));
48:  action.type = VELAWEAR_ACTION_SHOW_UI;
49:  action.priority = VELAWEAR_PRIORITY_CRITICAL;
50:  snprintf(action.params.display.text, sizeof(action.params.display.text),
51:           "FALL DETECTED!\nPlease check the wearer.");
52:  ret = action_manager_execute(engine->actions, &action);
53:  if (ret < 0)
54:    {
55:      return ret;
56:    }
57:
58:  memset(&action, 0, sizeof(action));
59:  action.type = VELAWEAR_ACTION_VIBRATE;
60:  action.priority = VELAWEAR_PRIORITY_CRITICAL;
61:  action.params.vibrate.duration_ms = 3000;
62:  action.params.vibrate.pattern = 8; /* SOS: ... --- ... */
63:  ret = action_manager_execute(engine->actions, &action);
64:  if (ret < 0)
65:    {
66:      return ret;
67:    }
68:
69:  memset(&action, 0, sizeof(action));
70:  action.type = VELAWEAR_ACTION_SEND_BLE;
71:  action.priority = VELAWEAR_PRIORITY_CRITICAL;
72:  snprintf(action.params.ble.data, sizeof(action.params.ble.data),
73:           "FALL DETECTED: emergency assistance required");
74:  action.params.ble.length = strlen(action.params.ble.data);
75:  ret = action_manager_execute(engine->actions, &action);
76:  if (ret < 0)
77:    {
78:      return ret;
79:    }
80:
81:  syslog(LOG_WARNING, "[Decision] FALL DETECTED! Emergency actions queued\n");
82:  return VELAWEAR_OK;
83:}
84:
85:static bool heart_rate_critical_condition(velawear_state_t *state,
86:                                          velawear_event_t *event,
87:                                          void *context)
88:{
89:  (void)event;
90:  (void)context;
91:  /* Zero is the driver's invalid/no-sensor value, not bradycardia. */
92:  return state->heart_rate > 0.0f &&
93:         (state->heart_rate > 180.0f || state->heart_rate < 40.0f);
94:}
