96:static int heart_rate_critical_action(velawear_state_t *state, void *context)
97:{
98:  syslog(LOG_WARNING, "[Decision] Heart rate critical: %.1f\n",
99:         state->heart_rate);
100:
101:  /* TODO: Show warning UI */
102:  /* TODO: Send BLE alert */
103:
104:  return VELAWEAR_OK;
105:}
106:
107:static bool battery_critical_condition(velawear_state_t *state,
108:                                       velawear_event_t *event,
109:                                       void *context)
110:{
111:  (void)event;
112:  (void)context;
113:  return state->battery_level < 5 && !state->is_charging;
114:}
115:
116:static int battery_critical_action(velawear_state_t *state, void *context)
117:{
118:  syslog(LOG_WARNING, "[Decision] Battery critical: %lu%%\n",
119:         (unsigned long)state->battery_level);
120:
121:  /* Switch to deep sleep mode */
122:  state->power_mode = VELAWEAR_POWER_DEEP_SLEEP;
123:
124:  return VELAWEAR_OK;
125:}
