127:/****************************************************************************
128: * Sedentary Reminder (Layer 1 - Configurable)
129: ****************************************************************************/
130:
131:static uint32_t sedentary_threshold_sec(velawear_engine_t *engine)
132:{
133:  if (engine != NULL && engine->config != NULL &&
134:      engine->config->sedentary_threshold_sec > 0)
135:    {
136:      return engine->config->sedentary_threshold_sec;
137:    }
138:
139:  return 45 * 60;
140:}
141:
142:static bool sedentary_condition(velawear_state_t *state,
143:                                velawear_event_t *event,
144:                                void *context)
145:{
146:  velawear_engine_t *engine = (velawear_engine_t *)context;
147:  uint32_t now;
148:
149:  if (event == NULL || event->type != VELAWEAR_EVENT_MOTION ||
150:      state == NULL || state->is_moving || state->last_move_time == 0)
151:    {
152:      return false;
153:    }
154:
155:  now = (uint32_t)time(NULL);
156:  return now >= state->last_move_time &&
157:         now - state->last_move_time >= sedentary_threshold_sec(engine);
158:}
159:
160:static int sedentary_action(velawear_state_t *state, void *context)
161:{
162:  velawear_engine_t *engine = (velawear_engine_t *)context;
163:  velawear_action_t action;
164:  uint32_t now;
165:  uint32_t cooldown_sec = 5 * 60;
166:  int ret;
167:
168:  if (engine == NULL || engine->actions == NULL)
169:    {
170:      return VELAWEAR_ERR_INVAL;
171:    }
172:
173:  now = (uint32_t)time(NULL);
174:  if (engine->last_sedentary_reminder != 0 &&
175:      now >= engine->last_sedentary_reminder &&
176:      now - engine->last_sedentary_reminder < cooldown_sec)
177:    {
178:      return VELAWEAR_OK;
179:    }
180:
181:  memset(&action, 0, sizeof(action));
182:  action.type = VELAWEAR_ACTION_SHOW_UI;
183:  action.priority = VELAWEAR_PRIORITY_NORMAL;
184:  snprintf(action.params.display.text, sizeof(action.params.display.text),
185:           "该活动一下了\n检测到持续静止");
186:
187:  ret = action_manager_execute(engine->actions, &action);
188:  if (ret == VELAWEAR_OK)
189:    {
190:      engine->last_sedentary_reminder = now;
191:      syslog(LOG_INFO,
192:             "[Decision] Sedentary reminder queued after %lu s\n",
193:             (unsigned long)sedentary_threshold_sec(engine));
194:    }
195:
196:  return ret;
197:}
