275:int decision_engine_init(velawear_engine_t *engine, velawear_config_t *config)
276:{
277:  memset(engine, 0, sizeof(velawear_engine_t));
278:
279:  pthread_mutex_init(&engine->lock, NULL);
280:  engine->config = config;
281:  engine->running = false;
282:
283:  /* Register hardcoded emergency rules */
284:
285:  decision_engine_add_rule(engine, "fall_detected", 0,
286:                           VELAWEAR_PRIORITY_CRITICAL,
287:                           fall_detected_condition,
288:                           fall_detected_action, engine);
289:
290:  decision_engine_add_rule(engine, "heart_rate_critical", 0,
291:                           VELAWEAR_PRIORITY_CRITICAL,
292:                           heart_rate_critical_condition,
293:                           heart_rate_critical_action, NULL);
294:
295:  decision_engine_add_rule(engine, "battery_critical", 0,
296:                           VELAWEAR_PRIORITY_HIGH,
297:                           battery_critical_condition,
298:                           battery_critical_action, NULL);
299:
300:  decision_engine_add_rule(engine, "sedentary_reminder", 1,
301:                           VELAWEAR_PRIORITY_NORMAL,
302:                           sedentary_condition,
303:                           sedentary_action, engine);
304:
305:  syslog(LOG_INFO, "[Decision] Initialized with %d rules\n",
306:         engine->rule_count);
307:  return VELAWEAR_OK;
308:}
309:
310:int decision_engine_start(velawear_engine_t *engine)
311:{
312:  int ret;
313:
314:  if (engine->running)
315:    {
316:      return VELAWEAR_ERR_BUSY;
317:    }
318:
319:  engine->running = true;
320:
321:  ret = pthread_create(&engine->thread, NULL, decision_engine_thread, engine);
322:  if (ret != 0)
323:    {
324:      syslog(LOG_ERR, "[Decision] Failed to create thread: %d\n", ret);
325:      engine->running = false;
326:      return VELAWEAR_ERR_IO;
327:    }
328:
329:  syslog(LOG_INFO, "[Decision] Started\n");
330:  return VELAWEAR_OK;
331:}
332:
333:int decision_engine_set_action_manager(velawear_engine_t *engine,
334:                                        velawear_actions_t *actions)
335:{
336:  if (engine == NULL || actions == NULL)
337:    {
338:      return VELAWEAR_ERR_INVAL;
339:    }
340:
341:  pthread_mutex_lock(&engine->lock);
342:  engine->actions = actions;
343:  pthread_mutex_unlock(&engine->lock);
344:  return VELAWEAR_OK;
345:}
346:
347:void decision_engine_cleanup(velawear_engine_t *engine)
348:{
349:  if (engine->running)
350:    {
351:      engine->running = false;
352:      pthread_join(engine->thread, NULL);
353:    }
354:
355:  pthread_mutex_destroy(&engine->lock);
356:
357:  syslog(LOG_INFO, "[Decision] Cleaned up\n");
358:}
